"""py-04：用哈希表把 O(n^2) 的查找改成 O(n)，并验证 __eq__ / __hash__ 的契约。"""

from collections import Counter, defaultdict


class Item:
    """按 (sku, warehouse) 判等的商品；__eq__ 与 __hash__ 必须成对定义。"""

    __slots__ = ("sku", "warehouse")

    def __init__(self, sku: str, warehouse: str) -> None:
        self.sku = sku
        self.warehouse = warehouse

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Item):
            return NotImplemented
        return (self.sku, self.warehouse) == (other.sku, other.warehouse)

    def __hash__(self) -> int:
        return hash((self.sku, self.warehouse))

    def __repr__(self) -> str:
        return f"Item({self.sku!r}, {self.warehouse!r})"


class Bad:
    """只定义 __eq__，Python 会把 __hash__ 置为 None，实例不可哈希。"""

    def __eq__(self, other: object) -> bool:
        return True


users = [
    {"id": "u1", "phone": "138-0001", "city": "sh"},
    {"id": "u2", "phone": "138-0002", "city": "bj"},
    {"id": "u3", "phone": "138-0003", "city": "sh"},
]
orders = [
    {"order_id": "o1", "user_id": "u2", "amount": 30},
    {"order_id": "o2", "user_id": "u1", "amount": 12},
    {"order_id": "o3", "user_id": "u3", "amount": 45},
    {"order_id": "o4", "user_id": "u2", "amount": 8},
]

# 1) 先建索引：一次 O(n)，之后每次查询 O(1)
by_id = {u["id"]: u for u in users}
print([by_id[o["user_id"]]["phone"] for o in orders])
# ['138-0002', '138-0001', '138-0003', '138-0002']

# 2) 插入顺序是语言保证；删除再插入会排到末尾
ordered = {"a": 1, "b": 2, "c": 3}
del ordered["b"]
ordered["b"] = 2
print(list(ordered))                 # ['a', 'c', 'b']
print(by_id.get("u9", "查无此人"))    # 查无此人

# 3) setdefault 不改变字典类型，defaultdict 读缺失键就会插入
buckets: dict[str, list[dict]] = {}
for order in orders:
    buckets.setdefault(order["user_id"], []).append(order)
print({k: len(v) for k, v in buckets.items()})     # {'u2': 2, 'u1': 1, 'u3': 1}

city_total: defaultdict[str, int] = defaultdict(int)
for order in orders:
    city_total[by_id[order["user_id"]]["city"]] += order["amount"]
print(dict(city_total))                            # {'bj': 38, 'sh': 57}

# 4) Counter：计数、取前 N
print(Counter(u["city"] for u in users).most_common(1))   # [('sh', 2)]

# 5) 集合运算：并、交、差、对称差；集合无序，要稳定输出就排序
paid_by_u1 = {o["order_id"] for o in orders if o["user_id"] == "u1"}
paid_by_u2 = {o["order_id"] for o in orders if o["user_id"] == "u2"}
print(sorted(paid_by_u1 | paid_by_u2))       # ['o1', 'o2', 'o4']
print(sorted(paid_by_u1 & paid_by_u2))       # []
print(sorted(paid_by_u2 - paid_by_u1))       # ['o1', 'o4']
print(sorted(paid_by_u1 ^ paid_by_u2))       # ['o1', 'o2', 'o4']

# 6) 自定义对象：eq/hash 成对，去重才生效
print(len({Item("A1", "sh"), Item("A1", "sh"), Item("A1", "bj")}))   # 2

try:
    {Bad()}
except TypeError as err:
    print(err)                       # unhashable type: 'Bad'

# 7) 改了参与哈希的字段，键就"漂移"了，旧记录再也取不出来
item = Item("A1", "sh")
index = {item: 1}
item.warehouse = "bj"
print(index.get(item, "key 丢了"))    # key 丢了
print(len(index))                    # 1，旧键仍占着位置

# 8) 量级对比：双重循环 vs 建索引
def slow_count(rows, targets):
    hits = 0
    for row in rows:                 # O(n*m)
        for target in targets:
            if target["id"] == row["user_id"]:
                hits += 1
                break
    return hits


def fast_count(rows, targets):
    by_key = {t["id"]: t for t in targets}   # 一次 O(m)
    return sum(1 for row in rows if row["user_id"] in by_key)   # 每次 O(1)


big_orders = [{"order_id": f"o{i}", "user_id": f"u{i % 500}", "amount": i} for i in range(4000)]
big_users = [{"id": f"u{i}", "phone": f"p{i}", "city": "sh" if i % 2 else "bj"} for i in range(500)]
print(slow_count(big_orders, big_users), fast_count(big_orders, big_users))  # 4000 4000

