"""py-05：让自定义对象像内建类型一样工作（Python 3.11 标准库，直接运行）。"""

from dataclasses import dataclass
from functools import total_ordering


@total_ordering
class Money:
    """不可变金额：可打印、可比较、可哈希、可相加。"""

    __slots__ = ("_cents", "currency")

    def __init__(self, cents: int, currency: str = "CNY") -> None:
        if cents < 0:
            raise ValueError(f"金额不能为负: {cents}")
        self._cents = cents
        self.currency = currency

    @property
    def cents(self) -> int:
        return self._cents

    @property
    def yuan(self) -> str:
        return f"{self._cents / 100:.2f}"

    def __repr__(self) -> str:
        return f"Money({self._cents}, {self.currency!r})"

    def __str__(self) -> str:
        return f"{self.yuan} {self.currency}"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Money):
            return NotImplemented
        return (self._cents, self.currency) == (other._cents, other.currency)

    def __hash__(self) -> int:
        return hash((self._cents, self.currency))

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, Money):
            return NotImplemented
        if self.currency != other.currency:
            raise ValueError("不同币种不能比较大小")
        return self._cents < other._cents

    def __add__(self, other: "Money") -> "Money":
        if not isinstance(other, Money):
            return NotImplemented
        if self.currency != other.currency:
            raise ValueError("不同币种不能相加")
        return Money(self._cents + other._cents, self.currency)


a = Money(1299)
b = Money(50)
print(repr(a))                        # Money(1299, 'CNY')
print(str(a), a.yuan)                 # 12.99 CNY 12.99
print(a + b, a > b)                   # 13.49 CNY True
print(len({a, Money(1299)}))          # 1
print(a == Money(1299, "USD"))        # False

# 特殊方法按类型查找：实例上打补丁只影响显式调用
class Plain:
    def __len__(self) -> int:
        return 2


p = Plain()
p.__len__ = lambda: 99                # 只挂在实例字典上
print(len(p), p.__len__())            # 2 99

# 类属性只有一份：把可变容器写在类体里，所有实例共享
class Cart:
    items: list[str] = []

    def add(self, sku: str) -> None:
        self.items.append(sku)        # 改的是类属性那一份


Cart().add("A")
Cart().add("B")
print(Cart.items)                     # ['A', 'B']


# dataclass：frozen 才生成 __hash__，普通 dataclass 不可哈希
@dataclass(frozen=True, order=True)
class Version:
    major: int
    minor: int = 0
    tags: tuple[str, ...] = ()


print(Version(1, 2) < Version(1, 10))              # True
print(hash(Version(1, 2)) == hash(Version(1, 2)))  # True


@dataclass
class Draft:
    title: str


print(Draft.__hash__)                 # None
try:
    {Draft("x")}
except TypeError as err:
    print(err)                        # unhashable type: 'Draft'

# super() 走 MRO 的下一环，不是简单调用"父类"
class Base:
    def describe(self) -> list[str]:
        return ["base"]


class Mid(Base):
    def describe(self) -> list[str]:
        return super().describe() + ["mid"]


class Leaf(Mid):
    def describe(self) -> list[str]:
        return super().describe() + ["leaf"]


print(Leaf().describe())              # ['base', 'mid', 'leaf']
print([c.__name__ for c in Leaf.__mro__])   # ['Leaf', 'Mid', 'Base', 'object']

"""py-06：异常链、上下文管理器与流式读文件（Python 3.11 标准库，直接运行）。"""

from contextlib import contextmanager
from pathlib import Path
from tempfile import TemporaryDirectory


class ConfigError(Exception):
    """配置类错误的基类：带上路径与原因，日志里能直接定位。"""

    def __init__(self, path: str, reason: str) -> None:
        super().__init__(f"{path}: {reason}")
        self.path = path
        self.reason = reason


@contextmanager
def step(name: str):
    """生成器版上下文管理器：yield 之前是 __enter__，之后是 __exit__。"""
    print(f"-> {name}")
    try:
        yield
    except Exception as err:
        print(f"<- {name} 失败: {type(err).__name__}")
        raise
    else:
        print(f"<- {name} 完成")


class Transaction:
    """类版上下文管理器：记录提交或回滚，但不吞异常。"""

    def __init__(self) -> None:
        self.log: list[str] = []

    def __enter__(self) -> "Transaction":
        self.log.append("begin")
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        if exc_type is None:
            self.log.append("commit")
        else:
            self.log.append(f"rollback:{exc_type.__name__}")
        return False  # 返回 False 表示不抑制异常


def sum_amounts(path: Path) -> int:
    """逐行累加金额；坏数据包装成 ConfigError，并保留原始异常。"""
    total = 0
    with path.open(encoding="utf-8", newline="") as fh:
        next(fh)  # 跳过表头，缺失时直接 StopIteration
        for lineno, line in enumerate(fh, start=2):
            raw = line.strip()
            if not raw:
                continue
            _, amount = raw.split(",")
            try:
                total += int(amount)
            except ValueError as err:
                raise ConfigError(path.name, f"第 {lineno} 行金额非法: {amount!r}") from err
    return total


with TemporaryDirectory() as tmp:
    path = Path(tmp) / "orders.csv"

    # 1) 坏数据：ConfigError 带上行号，__cause__ 是原始 ValueError
    path.write_text("id,amount\nu1,30\nu2,\nu3,45\n", encoding="utf-8")
    try:
        with step("读取订单"):
            print(sum_amounts(path))
    except ConfigError as err:
        print("捕获:", err)                              # orders.csv: 第 3 行金额非法: ''
        print("原因:", type(err.__cause__).__name__)      # ValueError

    # 2) 修好数据后正常返回
    path.write_text("id,amount\nu1,30\nu2,12\n", encoding="utf-8")
    print(sum_amounts(path))                             # 42

    # 3) 编码不匹配：GBK 字节按 UTF-8 解，立刻抛错而不是读出乱码
    try:
        "价格,12".encode("gbk").decode("utf-8")
    except UnicodeDecodeError as err:
        print("编码不匹配:", err.reason)                  # invalid start byte

    # 4) 上下文管理器：正常路径提交，异常路径回滚且不吞异常
    with Transaction() as tx:
        tx.log.append("扣款")
    print(tx.log)                                        # ['begin', '扣款', 'commit']

    try:
        with Transaction() as tx2:
            tx2.log.append("扣款")
            raise RuntimeError("余额不足")
    except RuntimeError as err:
        print(tx2.log, err)                              # ['begin', '扣款', 'rollback:RuntimeError'] 余额不足

    # 5) finally 里 return 会吞掉异常、覆盖返回值
    def swallow() -> str:
        try:
            raise ValueError("boom")
        finally:
            return "swallowed"

    print(swallow())                                     # swallowed（异常消失了）

    # 6) 逐行迭代：内存占用与文件大小无关
    path.write_text("id,amount\n" + "".join(f"u{i},{i}\n" for i in range(1, 101)), encoding="utf-8")
    lines = 0
    with path.open(encoding="utf-8", newline="") as fh:
        for line in fh:
            if line.strip():
                lines += 1
    print("非空行:", lines)                               # 101（含表头）

"""装饰器与上下文管理器：参数化重试、调用计数、计时与异常抑制。

运行：python decorators_demo.py（Python 3.11 + 标准库）
示例输出：
    第 1 次失败：第 1 次调用失败
    第 2 次失败：第 2 次调用失败
结果 42
__name__ = flaky
签名 = (value: int) -> int
原始函数 = flaky
add 被调用 2 次，__name__ = add
堆叠顺序：
    -> 进入 outer
    -> 进入 inner
    ... 函数体执行
    <- 退出 inner
    <- 退出 outer
异常抑制：
    [demo] 已吞掉异常：可恢复的错误
    with 块之后仍然继续执行
重试耗尽：
    第 1 次失败：不可恢复
    第 2 次失败：不可恢复
    捕获到 不可恢复
"""
import functools
import inspect
import time
from contextlib import contextmanager


def retry(times: int = 3, delay: float = 0.0):
    """带参数的装饰器：retry(times=3) 先返回装饰器，再装饰函数。"""

    def decorator(func):
        @functools.wraps(func)  # 保留 __name__/__doc__/__wrapped__
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except ValueError as exc:
                    print(f'    第 {attempt} 次失败：{exc}')
                    if attempt == times:
                        raise  # 重试耗尽必须如实上报
                    time.sleep(delay)
        return wrapper

    return decorator


class CountCalls:
    """类装饰器：状态放在实例上，比闭包里的 nonlocal 更好读。"""

    def __init__(self, func):
        functools.update_wrapper(self, func)
        self.func = func
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        return self.func(*args, **kwargs)


@contextmanager
def timed(label: str):
    """yield 之前是 __enter__，yield 之后（finally）是 __exit__。"""
    start = time.perf_counter()
    try:
        yield
    finally:
        print(f'    {label} 耗时 {time.perf_counter() - start:.4f}s')


@contextmanager
def suppress_value_error(tag: str):
    """在 yield 处捕获异常并正常结束，等于 __exit__ 返回真值。"""
    try:
        yield
    except ValueError as exc:
        print(f'    [{tag}] 已吞掉异常：{exc}')


def trace(name: str):
    """用来演示堆叠顺序：外层先进入、最后退出。"""

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            print(f'    -> 进入 {name}')
            result = func(*args, **kwargs)
            print(f'    <- 退出 {name}')
            return result
        return wrapper

    return decorator


@retry(times=3, delay=0.01)
def flaky(value: int) -> int:
    """前两次调用抛 ValueError，第三次成功。"""
    flaky.attempts += 1
    if flaky.attempts < 3:
        raise ValueError(f'第 {flaky.attempts} 次调用失败')
    return value * 2


flaky.attempts = 0  # 函数属性：装饰之后仍然可以挂


@CountCalls
def add(a: int, b: int) -> int:
    """把两个数相加。"""
    return a + b


@trace('outer')
@trace('inner')
def stacked() -> None:
    print('    ... 函数体执行')


@retry(times=2)
def always_fail() -> None:
    raise ValueError('不可恢复')


def main() -> None:
    with timed('重试流程'):
        print(f'结果 {flaky(21)}')

    print(f'__name__ = {flaky.__name__}')
    print(f'签名 = {inspect.signature(flaky)}')
    print(f'原始函数 = {flaky.__wrapped__.__name__}')

    add(1, 2)
    add(3, 4)
    print(f'add 被调用 {add.calls} 次，__name__ = {add.__name__}')

    print('堆叠顺序：')
    stacked()

    print('异常抑制：')
    with suppress_value_error('demo'):
        raise ValueError('可恢复的错误')
    print('    with 块之后仍然继续执行')

    print('重试耗尽：')
    try:
        always_fail()
    except ValueError as exc:
        print(f'    捕获到 {exc}')


if __name__ == '__main__':
    main()

